def minOperations(nums, k):
    n = len(nums)

    # even_cost[t] / odd_cost[t]: total operations so that every element
    # at even / odd indices has remainder t modulo k
    even_cost = [0] * k
    odd_cost = [0] * k

    for i in range(n):
        r = nums[i] % k
        for t in range(k):
            d = r - t
            if d < 0:
                d = -d
            # Remainders sit on a circle of size k, so we can go either way around
            step = min(d, k - d)
            if i % 2 == 0:
                even_cost[t] += step
            else:
                odd_cost[t] += step

    # Try every pair of distinct targets (x for even indices, y for odd indices)
    best = None
    for x in range(k):
        for y in range(k):
            if x == y:
                continue
            total = even_cost[x] + odd_cost[y]
            if best is None or total < best:
                best = total

    return best
